head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.contnId;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_save_onclick = function() {
    try {
        if (scwin.contnId === "input") {
            scwin.save();
        } else {
            scwin.update();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.btn_save_onclick" });
    }
};

scwin.trs_Save_OnSuccess = async function() {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "HelpDesk 등록"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Save_OnSuccess" });
    }
};

scwin.trs_Save_OnFail = function() {
    try {
        alert($c.stf.getMessageParam("MSG-A002", "HelpDesk 등록"));
        alert(trs_Save.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Save_OnFail" });
    }
};

scwin.trs_Update_OnSuccess = async function() {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "HelpDesk 수정"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Update_OnSuccess" });
    }
};

scwin.trs_Update_OnFail = function() {
    try {
        alert($c.stf.getMessageParam("MSG-A002", "HelpDesk 수정"));
        alert(trs_Update.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Update_OnFail" });
    }
};

scwin.trs_Delete_OnSuccess = async function() {
    try {
        alert($c.stf.getMessageParam("MSG-A001", "HelpDesk 삭제"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Delete_OnSuccess" });
    }
};

scwin.trs_Delete_OnFail = function() {
    try {
        alert($c.stf.getMessageParam("MSG-A002", "HelpDesk 삭제"));
        alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.trs_Delete_OnFail" });
    }
};

scwin.inf_find_OnClick = function() {
    try {
        const filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
        if (scwin.contnId === "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
            file_name.setValue(inf_find.Value);
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.Value);
        }
        if (inf_find.Value === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.inf_find_OnClick" });
    }
};

scwin.btn_lineadd_onclick = function() {
    try {
        if (dts_fileList.getRowCount() === 5) {
            alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_fileList.insertRow();

        inf_find.open();
        if (inf_find.Value !== "") {
            if (scwin.contnId === "input") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
                file_name.setValue(inf_find.Value);
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
                file_name.setValue(inf_find.Value);
            }
        } else {
            dts_fileList.removeRows(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.btn_lineadd_onclick" });
    }
};

scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRows(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.btn_linedelete_onclick" });
    }
};

scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30301.btn_cancel_onclick" });
    }
};

scwin.btn_delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.btn_delete_onclick" });
    }
};

scwin.grd_fileList_OnClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30301.grd_fileList_OnClick" });
    }
};

scwin.rdo_Procs_Stat_onselchange = function() {

};

///////// 4. 서브미션 콜백 영역 /////////
scwin.read = async function() {

    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/ShareRoom.do",
        ref : "dts_ShareRoomInfo,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

scwin.save = async function() {
    if (dts_fileList.getCellData(1, "fileInfo") === "") {

        dts_fileList.Reset();
    }
    if (cmb_Creatloc_Tp_Cd.getValue() === "99") {
        // alert( getMessageParam("MSG-A005", "시스템구분") );
        alert("[시스템구분] 을(를) 선택하셔야 합니다.");
        cmb_Creatloc_Tp_Cd.focus();
        return;
    }
    if (tbox_title.getValue() === "") {
        alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    let rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        tbox_wrtr_emp_nm.setValue(js_emp_no);

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ShareRoom.do",
            ref : "dts_ShareRoomInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

scwin.delete = async function() {
    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_ShareRoomDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ShareRoomDel.insertRow();
        dts_ShareRoomDel.setCellData(1, "CONTN_ID", scwin.contnId);

        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/ShareRoom.do",
            ref : "dts_ShareRoomDel",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

scwin.update = async function() {
    if (cmb_Creatloc_Tp_Cd.getValue() === "99") {
        // alert( getMessageParam("MSG-A005", "시스템구분") );
        alert("[시스템구분] 을(를) 선택하셔야 합니다.");
        cmb_Creatloc_Tp_Cd.focus();
        return;
    }
    if (tbox_title.getValue() === "") {
        alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/ShareRoom.do",
            ref : "dts_ShareRoomInfo,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

scwin.setSaveHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_ShareRoomInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ShareRoomInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_ShareRoomInfo.insertRow();
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.setDataHeader = function() {

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};

// 파일 다운로드
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.contnId + "&attach_seq=" + attach_seq + "&gubun=2";
};

scwin.checkMaxLength1 = function(obj, size, lbl) {
    let overLen = eval($c.stf.getStringSize(obj.value) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.checkMaxLength2 = function(obj, size, lbl) {
    let overLen = eval($c.stf.getStringSize(obj.text) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    tbox_mkt_tp.hide();
    // showObj(btn_save, false);
    // getContnId= "input";//frame.Provider("../").fn_getContnId; 
    // contnId = "input";//getContnId();

    const parentYn = $c.frame.path("../").scwin.contnId;
    // alert('parentYn =>'+ parentYn);

    if (parentYn === null || parentYn === "undefined" || parentYn.length === 0) {
        scwin.contnId = "input";
    } else {

        getContnId = $c.frame.path("../").fn_getContnId;

        scwin.contnId = getContnId();
    }
    if (scwin.contnId !== "input") {
        scwin.read();

        // 현업이 로그인 했을시 (js_usr_tp_cd - 현업 : 4, 운영자 : 1)
        if (js_usr_tp_cd === '4') {
            // 현업은 수정시
            if (rdo_Procs_Stat.getValue() === '10') {
                // 처리상태 - 신규
                rdo_Procs_Stat.Format = "10^신규,20^처리중^disabled,30^처리완료^disabled,40^최종확인^disabled,50^반려^disabled,60^기타^disabled";
            } else if (rdo_Procs_Stat.getValue() === '20') {
                // 처리상태 - 처리중
                rdo_Procs_Stat.Format = "10^신규^disabled,20^처리중^disabled,30^처리완료^disabled,40^최종확인^disabled,50^반려^disabled,60^기타^disabled";

                // 처리 상태가 처리중일때 저장,삭제 버튼 안보이게 처리
                btn_save.hide();
                btn_delete.hide();
            } else if (rdo_Procs_Stat.getValue() === '30') {
                // 처리상태 - 개발완료
                rdo_Procs_Stat.Format = "10^신규^disabled,20^처리중^disabled,30^처리완료^disabled,40^최종확인,50^반려^disabled,60^기타^disabled";

                // 처리 상태가 개발완료중일때 삭제 버튼 안보이게 처리
                btn_delete.hide();
            } else {
                // 처리상태 - 최종확인, 반려, 기타
                rdo_Procs_Stat.Format = "10^신규^disabled,20^처리중^disabled,30^처리완료^disabled,40^최종확인^disabled,50^반려^disabled,60^기타^disabled";

                // 처리 상태가 처리중일때 저장,삭제 버튼 안보이게 처리
                btn_save.hide();
                btn_delete.hide();
            }
        } else {
            rdo_Procs_Stat.Format = "10^신규,20^처리중,30^처리완료,40^최종확인,50^반려,60^기타";
        }
    } else {
        scwin.setDataHeader();
        scwin.setSaveHeader();
        tbox_wrtr_emp_nm.setValue(js_emp_nm);
        tbox_wrt_ddtm.setValue($c.ut.cGetToday("yyyymmdd"));
        tbox_inq_cnt.setValue("0");
        tbox_mkt_tp.setValue(js_market);
        // 처리상태 추가(2013.09.27)
        rdo_Procs_Stat.setValue("10");
        // 시스템구분 추가
        cmb_Creatloc_Tp_Cd.setValue("99");

        // 신규입력시 삭제 버튼 안보이게 처리
        btn_delete.hide();

        // 현업이 로그인 했을시 (js_usr_tp_cd - 현업 : 4, 운영자 : 1)
        if (js_usr_tp_cd === '4') {
            // 현업은 등록시 신규로만 가능
            rdo_Procs_Stat.Format = "10^신규";
        } else {
            // 운영자는 모두 가능
            rdo_Procs_Stat.Format = "10^신규";
        }
    }
};
